cards.solution:
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> skor = new ArrayList<>();
        skor.add(250);
        skor.add(250);
        System.out.println(skor.get(0) == skor.get(1));
        System.out.println(skor.get(0).equals(skor.get(1)));
    }
}

